@article{Schmalstieg_406,
  selected={1},
  author={Shohei Mori and Dieter Schmalstieg and Denis Kalkofen},
  journal={IEEE Transactions on Visualization and Computer Graphics}, 
  title={Good Keyframes to Inpaint}, 
  year={2022},
  url = {http://arbook.icg.tugraz.at/schmalstieg/Schmalstieg_406.pdf},
  video = {https://youtu.be/a0JOzRNFnag},
  abstract={Diminished Reality (DR) propagates pixels from a keyframe to subsequent frames for real-time inpainting. Keyframe selection has a significant impact on the inpainting quality, but untrained users struggle to identify good keyframes. Automatic selection is not straightforward either, since no previous work has formalized or verified what determines a good keyframe. We propose a novel metric to select good keyframes to inpaint. We examine the heuristics adopted in existing DR inpainting approaches and derive multiple simple criteria measurable from SLAM. To combine these criteria, we empirically analyze their effect on the quality using a novel representative test dataset. Our results demonstrate that the combined metric selects RGBD keyframes leading to high-quality inpainting results more often than a baseline approach in both color and depth domains. Also, we confirmed that our approach has a better ranking ability of distinguishing good and bad keyframes. Compared to random selections, our metric selects keyframes that would lead to higher-quality and more stably converging inpainting results. We present three DR examples, automatic keyframe selection, user navigation, and marker hiding.}
}

@article{Schmalstieg_407,
  selected={1},
  author={Fernando Reyes-Aviles and Philipp Fleck and Dieter Schmalstieg and Clemens Arth},
  journal={IEEE Transactions on Visualization and Computer Graphics}, 
  title={Compact World Anchors: Registration Using Parametric Primitives as Scene Description}, 
  year={2022},
  url = {http://arbook.icg.tugraz.at/schmalstieg/Schmalstieg_407.pdf},
  video={https://www.youtube.com/watch?v=T1Rs_1MxXHA},
  abstract={We present a registration method relying on geometric constraints extracted from parametric primitives contained in 3D parametric models. Our method solves the registration in closed-form from three line-to-line, line-to-plane or plane-to-plane correspondences. The approach either works with semantically segmented RGBD scans of the scene or with the output of plane detection in common frameworks like ARKit and ARCore. Based on the primitives detected in the scene, we build a list of descriptors using the normals and centroids of all the found primitives, and match them against the pre-computed list of descriptors from the model in order to find the scene-to-model primitive correspondences. Finally, we use our closed-form solver to estimate the 6DOF transformation from three lines and one point, which we obtain from the parametric representations of the model and scene parametric primitives. Quantitative and qualitative experiments on synthetic and real-world data sets demonstrate the performance and robustness of our method. We show that it can be used to create compact world anchors for indoor localization in AR applications on mobile devices leveraging commercial SLAM capabilities.}
}

@article{Schmalstieg_408,
  selected={1},
  author={Ana Stanescu and Peter Mohr and Dieter Schmalstieg and Denis Kalkofen},
  journal={IEEE Transactions on Visualization and Computer Graphics}, 
  title={Model-Free Authoring by Demonstration of Assembly Instructions in Augmented Reality}, 
  year={2022},
  url = {http://arbook.icg.tugraz.at/schmalstieg/Schmalstieg_408.pdf},
  video={https://youtu.be/vk_xcGKkgYQ},
  abstract={Among the most compelling applications of Augmented Reality are spatially registered tutorials. The effort of creating such instructions remains one of the obstacles precluding a wider use. We propose a system that is capable of extracting 3D instructions in a completely model-free manner from demonstrations, based on volumetric changes. The instructions are visualised later in an interactive Augmented Reality guidance application, on a mobile head-mounted display. We enable a technology that can be used by anyone in an ad-hoc tabletop setup for assemblies with rigid components.}
}
